                resolve(response)
            } catch (error) {
                console.log(error);
                if (error.response && error.response.status === 401 && config.uri !== '/auth') {
                    window.location.href = "/"
                    // location.href = process.env.PUBLIC_URL
                } else {
                    reject(error)
                }
            }
        })
    }
}
